/* The JPEG drain configuration, as bk7258_camera_imgdata.c builds it: a
 * fixed FIFO source with the JPEG request line, an incrementing looping
 * destination, REPEAT, 32-bit units.
 */

static void jpeg_like_cfg(struct bk7258_dma_cfg_s *cfg, uint8_t ch)
{
  memset(cfg, 0, sizeof(*cfg));
  cfg->channel         = ch;
  cfg->src_addr        = 0x48000014u;   /* JPEG rx_fifo_data */
  cfg->dest_addr       = 0x60200000u;
  cfg->transfer_len    = 10240u;
  cfg->src_dev         = BK7258_DMA_DEV_JPEG;
  cfg->dest_dev        = BK7258_DMA_DEV_MEM;
  cfg->src_inc         = false;
  cfg->dest_inc        = true;
  cfg->repeat          = true;
  cfg->dest_loop_start = 0x60200000u;
  cfg->dest_loop_end   = 0x60200000u + 0x40000u;
  cfg->data_width      = BK7258_DMA_WIDTH_32BITS;
}

static void test_ex_programs_request_lines(void)
{
  struct bk7258_dma_cfg_s cfg;
  uint32_t req;

  bk7258_sim_reset();
  jpeg_like_cfg(&cfg, 0);
  CHECK(bk7258_dma_configure_ex(&cfg) == 0, "expected configure_ex to accept");

  req = bk7258_sim_peek32(TEST_DMA_CH_REQ_MUX(0));

  /* 0x19 is the hardware's req_mux encoding for JPEG, which is NOT the
   * vendor enum's index (28).  Pinned here because getting it wrong makes
   * the channel wait forever on a request that never arrives, with no error
   * anywhere.
   */

  CHECK((req & 0x1fu) == 0x19u,
        "expected src_req_mux 0x19 (JPEG), got 0x%x", req & 0x1fu);
  CHECK(((req >> 5) & 0x1fu) == 0x00u,
        "expected dest_req_mux 0 (memory), got 0x%x", (req >> 5) & 0x1fu);
}

static void test_ex_programs_repeat_loop_and_widths(void)
{
  struct bk7258_dma_cfg_s cfg;
  uint32_t ctrl;

  bk7258_sim_reset();
  jpeg_like_cfg(&cfg, 0);
  bk7258_dma_configure_ex(&cfg);

  ctrl = bk7258_sim_peek32(TEST_DMA_CH_CTRL(0));

  CHECK((ctrl & TEST_DMA_CTRL_MODE_BIT) != 0,
        "expected REPEAT mode, ctrl=0x%x", ctrl);
  CHECK((ctrl & TEST_DMA_CTRL_SRC_INC_EN) == 0,
        "expected a fixed source address for a FIFO, ctrl=0x%x", ctrl);
  CHECK((ctrl & TEST_DMA_CTRL_DEST_INC_EN) != 0,
        "expected an incrementing destination, ctrl=0x%x", ctrl);
  CHECK((ctrl & TEST_DMA_CTRL_DEST_LOOP_EN) != 0,
        "expected the destination loop enabled, ctrl=0x%x", ctrl);
  CHECK(((ctrl >> 4) & 0x3u) == BK7258_DMA_WIDTH_32BITS,
        "expected 32-bit source width, ctrl=0x%x", ctrl);
  CHECK(((ctrl >> 6) & 0x3u) == BK7258_DMA_WIDTH_32BITS,
        "expected 32-bit destination width, ctrl=0x%x", ctrl);
  CHECK(bk7258_sim_peek32(TEST_DMA_CH_LOOP_START(0)) == 0x60200000u,
        "expected the loop start address programmed");
  CHECK(bk7258_sim_peek32(TEST_DMA_CH_LOOP_END(0)) == 0x60240000u,
        "expected the loop end address programmed");
  CHECK((ctrl & TEST_DMA_CTRL_ENABLE) == 0,
        "configure must not start the channel, ctrl=0x%x", ctrl);
}

static void test_ex_rejects_bad_configuration(void)
{
  struct bk7258_dma_cfg_s cfg;

  bk7258_sim_reset();

  jpeg_like_cfg(&cfg, BK7258_DMA_NCHANNELS);
  CHECK(bk7258_dma_configure_ex(&cfg) != 0, "expected a bad channel to fail");

  jpeg_like_cfg(&cfg, 0);
  cfg.transfer_len = 0;
  CHECK(bk7258_dma_configure_ex(&cfg) != 0, "expected zero length to fail");

  jpeg_like_cfg(&cfg, 0);
  cfg.transfer_len = 0x10001u;
  CHECK(bk7258_dma_configure_ex(&cfg) != 0,
        "expected an oversized length to fail");

  jpeg_like_cfg(&cfg, 0);
  cfg.data_width = 3;
  CHECK(bk7258_dma_configure_ex(&cfg) != 0, "expected a bad width to fail");

  CHECK(bk7258_sim_peek32(TEST_DMA_CH_CTRL(0)) == 0,
        "a rejected configuration must not write any register");
}

static void test_legacy_configure_is_still_memory_to_memory(void)
{
  uint32_t ctrl;
  uint32_t req;

  bk7258_sim_reset();
  bk7258_dma_configure(0x60000000u, 0x28100000u, 4096u);

  ctrl = bk7258_sim_peek32(TEST_DMA_CTRL);
  req  = bk7258_sim_peek32(TEST_DMA_CH_REQ_MUX(0));

  /* The audio driver's comment describes this interface as it stands, so
   * routing it through configure_ex() must not have changed any of it.
   */

  CHECK((ctrl & TEST_DMA_CTRL_MODE_BIT) == 0, "expected SINGLE mode");
  CHECK((ctrl & TEST_DMA_CTRL_SRC_INC_EN) != 0, "expected src increment");
  CHECK((ctrl & TEST_DMA_CTRL_DEST_INC_EN) != 0, "expected dest increment");
  CHECK((ctrl & TEST_DMA_CTRL_DEST_LOOP_EN) == 0, "expected no dest loop");
  CHECK(((ctrl >> 16) & 0xffffu) == 4096u - 1u, "expected len-1 encoding");
  CHECK(req == 0u, "expected both request lines to be memory, got 0x%x", req);
}

static void test_repeat_channel_stays_enabled_on_finish(void)
{
  struct bk7258_dma_cfg_s cfg;
  uint32_t ctrl;

  bk7258_sim_reset();
  bk7258_dma_init();
  bk7258_dma_set_channel_callback(0, test_done_cb, NULL);

  jpeg_like_cfg(&cfg, 0);
  bk7258_dma_configure_ex(&cfg);
  bk7258_dma_start_channel(0);

  g_done_cb_called = false;
  bk7258_sim_poke32(TEST_DMA_CH_STATUS(0), TEST_DMA_STATUS_FINISH_INT);
  bk7258_sim_dispatch_irq(BK7258_IRQ_DMA);

  ctrl = bk7258_sim_peek32(TEST_DMA_CH_CTRL(0));

  CHECK(g_done_cb_called == true, "expected the callback to fire");
  CHECK((ctrl & TEST_DMA_CTRL_ENABLE) != 0,
        "a REPEAT channel must keep running across a finish interrupt -- "
        "the interrupt is a progress report, not an end, ctrl=0x%x", ctrl);
}

static void test_isr_clears_finish_by_write_one(void)
{
  struct bk7258_dma_cfg_s cfg;
  uint32_t status;

  bk7258_sim_reset();
  bk7258_dma_init();
  bk7258_dma_set_channel_callback(0, test_done_cb, NULL);

  jpeg_like_cfg(&cfg, 0);
  bk7258_dma_configure_ex(&cfg);
  bk7258_dma_start_channel(0);

  /* remain_len is read-only and shares this register with three
   * write-1-to-clear interrupt bits, so the handler must write the one bit
   * it is acknowledging and nothing else.
   */

  bk7258_sim_poke32(TEST_DMA_CH_STATUS(0),
                    TEST_DMA_STATUS_FINISH_INT | 0x1234u);
  bk7258_sim_dispatch_irq(BK7258_IRQ_DMA);

  status = bk7258_sim_peek32(TEST_DMA_CH_STATUS(0));
  CHECK(status == TEST_DMA_STATUS_FINISH_INT,
        "expected the handler to write exactly the finish bit, got 0x%x",
        status);
}

static void test_flush_src_buffer_sets_only_that_bit(void)
{
  uint32_t status;

  bk7258_sim_reset();
  bk7258_dma_flush_src_buffer(0);

  status = bk7258_sim_peek32(TEST_DMA_CH_STATUS(0));
  CHECK(status == TEST_DMA_STATUS_FLUSH_SRC,
        "expected only flush_src_buff written (a read-modify-write would "
        "clear pending W1C interrupt bits), got 0x%x", status);
}

static void test_channels_are_independent(void)
{
  struct bk7258_dma_cfg_s cfg;

  bk7258_sim_reset();
  bk7258_dma_init();

  jpeg_like_cfg(&cfg, 3);
  bk7258_dma_configure_ex(&cfg);
  bk7258_dma_start_channel(3);

  CHECK(bk7258_sim_peek32(TEST_DMA_CH_CTRL(3)) & TEST_DMA_CTRL_ENABLE,
        "expected channel 3 running");
  CHECK(bk7258_sim_peek32(TEST_DMA_CH_CTRL(0)) == 0,
        "configuring channel 3 must not touch channel 0");
  CHECK(bk7258_dma_is_busy() == false,
        "the legacy is_busy() reports channel 0 only");

  /* A channel with no callback registered is not serviced, so a stale
   * finish bit on it cannot be mistaken for someone else's completion.
   */

  g_done_cb_called = false;
  bk7258_sim_poke32(TEST_DMA_CH_STATUS(3), TEST_DMA_STATUS_FINISH_INT);
  bk7258_sim_dispatch_irq(BK7258_IRQ_DMA);
  CHECK(g_done_cb_called == false,
        "expected no callback for a channel that has none registered");
}

