static void test_isr_invokes_callback_only_on_finish_bit(void)
{
  int dummy_arg = 42;
  bool fired;

  bk7258_sim_reset();
  bk7258_dma_init();
  bk7258_dma_set_done_callback(test_done_cb, &dummy_arg);
  g_done_cb_called = false;
  g_done_cb_arg_seen = NULL;

  /* Status register with finish_int NOT set: ISR must not invoke the
   * callback (e.g. a spurious/other-bit interrupt should not be
   * misreported as "transfer complete"). */
  bk7258_sim_poke32(TEST_DMA_STATUS, 0u);
  fired = bk7258_sim_irq_fire(BK7258_IRQ_DMA);
  CHECK(fired == true, "expected an ISR to be registered for IRQ_DMA");
  CHECK(g_done_cb_called == false,
        "expected the done callback NOT to fire when finish_int is "
        "clear in the status register");

  /* Now set finish_int: the ISR must invoke the callback with the
   * exact arg pointer that was registered. */
  bk7258_sim_poke32(TEST_DMA_STATUS, TEST_DMA_STATUS_FINISH_INT);
  (void)bk7258_sim_irq_fire(BK7258_IRQ_DMA);
  CHECK(g_done_cb_called == true,
        "expected the done callback to fire when finish_int is set");
  CHECK(g_done_cb_arg_seen == &dummy_arg,
        "expected the callback to receive the exact arg pointer "
        "registered via set_done_callback()");
}

